defense.secure_config:
# Audit all service binary permissions:
Get-WmiObject Win32_Service | ForEach-Object {
    $path = $_.PathName -replace '"',''
    if (Test-Path $path) {
        $acl = Get-Acl $path
        $acl.Access | Where-Object {$_.IdentityReference -match 'Users|Everyone'}
    }
}

# Fix permissive binary permissions:
icacls 'C:\Program Files\File Monitor\filepermservice.exe' /inheritance:r /grant 'SYSTEM:(F)' /grant 'Administrators:(F)'
